/**
 * Retrieves services from the catalog that match the given filters, each enriched with availability data.
 *
 * Applies location, resource type, and attribute filters, then narrows the catalog using the provided
 * WQL query. When a date range is specified in `serviceFilters`, only services with bookable slots in
 * that window are returned. Without a date range, all filtered services are returned, each marked as
 * available.
 *
 * To get complete result pages when filtering by availability, specify `query.cursorPaging`. Without it,
 * a single page of filtered results is returned without backfilling to the requested page size.
 * @public
 * @documentationMaturity preview
 * @permissionId bookings:catalog_search:v1:catalog_search:query_services_by_filters
 * @applicableIdentity APP
 * @fqn wix.bookings.catalog.search.v1.CatalogSearch.QueryServicesByFilters
 */
export async function queryServicesByFilters(
  options?: QueryServicesByFiltersOptions
): Promise<
  NonNullablePaths<
    QueryServicesByFiltersResponse,
    | `results`
    | `results.${number}.service.type`
    | `results.${number}.service.category._id`
    | `results.${number}.service.form._id`
    | `results.${number}.service.payment.rateType`
    | `results.${number}.service.payment.addOnOption`
    | `results.${number}.service.bookingPolicy._id`
    | `results.${number}.service.taxableAddress.taxableAddressType`
    | `results.${number}.available`,
    4
  >
> {
  // @ts-ignore
  const { httpClient, sideEffects } = arguments[1] as {
    httpClient: HttpClient;
    sideEffects?: any;
  };

  const payload = renameKeysFromSDKRequestToRESTRequest({
    query: options?.query,
    serviceFilters: options?.serviceFilters,
  });

  const reqOpts =
    ambassadorWixBookingsCatalogSearchV1CatalogSearch.queryServicesByFilters(
      payload
    );

  sideEffects?.onSiteCall?.();
  try {
    const result = await httpClient.request(reqOpts);
    sideEffects?.onSuccess?.(result);

    return renameKeysFromRESTResponseToSDKResponse(
      transformPaths(result.data, [
        {
          transformFn: transformRESTImageToSDKImage,
          paths: [
            { path: 'results.service.media.items.image' },
            { path: 'results.service.media.mainMedia.image' },
            { path: 'results.service.media.coverMedia.image' },
            { path: 'results.service.staffMembers.mainMedia.image' },
            {
              path: 'results.service.staffMemberDetails.staffMembers.mainMedia.image',
            },
          ],
        },
        {
          transformFn: transformRESTAddressToSDKAddress,
          paths: [
            { path: 'results.service.locations.calculatedAddress' },
            { path: 'results.service.locations.business.address' },
            { path: 'results.service.locations.custom.address' },
          ],
        },
        {
          transformFn: transformRESTPageURLV2ToSDKPageURLV2,
          paths: [
            { path: 'results.service.urls.servicePage' },
            { path: 'results.service.urls.bookingPage' },
            { path: 'results.service.urls.calendarPage' },
          ],
        },
      ])
    )!;
  } catch (err: any) {
    const transformedError = sdkTransformError(
      err,
      {
        spreadPathsToArguments: {},
        explicitPathsToArguments: {
          query: '$[0].query',
          serviceFilters: '$[0].serviceFilters',
        },
        singleArgumentUnchanged: false,
      },
      ['options']
    );
    sideEffects?.onError?.(err);

    throw transformedError;
  }
}

export interface QueryServicesByFiltersOptions {
  /**
   * Query against the service catalog: WQL filter, sort, and cursor paging.
   *
   * Default: `query.cursorPaging.limit` is `10`.
   */
  query?: CursorQuery;
  /**
   * Availability and resource constraints applied on top of the service query.
   * When absent, no availability check is performed and all pre-filtered services are returned.
   */
  serviceFilters?: ServiceFilters;
}
